'use strict';
let rift3d=null,rendererFailed=false;
const canvas3d=$('arena3d'),preview3d=$('heroPreview'),fallbackDraw=draw,fallbackPoint=canvasPoint;
function showGraphicsStatus(count,total){$('graphicsStatus').textContent=count<0?'โหลดโมเดลไม่สำเร็จ · ใช้ภาพสำรอง':count===total?'':'กำลังเตรียมสนาม 3D · '+count+' / '+total;document.body.classList.toggle('graphics-fallback',count<0);if(count===total)document.body.classList.add('three-ready');}
try{rift3d=Rift3D.create({canvas:canvas3d,previewCanvas:preview3d,routes:ROUTES,obstacles:OBSTACLES,bushes:BUSHES,onStatus:showGraphicsStatus,portraitCanvases:[...document.querySelectorAll(".model-portrait")]});canvas3d.hidden=false;showGraphicsStatus(0,HEROES.length);rift3d.loading.then(ok=>{if(!ok){rendererFailed=true;canvas3d.hidden=true;}});}catch(e){rendererFailed=true;canvas3d.hidden=true;showGraphicsStatus(-1,HEROES.length);console.warn('3D renderer unavailable',e.message);}
canvas3d.addEventListener('webglcontextlost',e=>{e.preventDefault();rendererFailed=true;canvas3d.hidden=true;document.body.classList.remove('three-ready');showGraphicsStatus(-1,HEROES.length);});
canvasPoint=function(e){if(rift3d&&!rendererFailed&&game){const rect=canvas.getBoundingClientRect();return rift3d.unproject(e.clientX-rect.left,e.clientY-rect.top);}return fallbackPoint(e);};
function manualSkillAim(dx,dy,p,key){const info=skillInfo(p,key),range=info.range||210;if(rift3d&&!rendererFailed){const from=rift3d.project(p.x,p.y),at=rift3d.unproject(from.x+dx,from.y+dy);return {...limitAim(p,at,range),manual:true};}const len=Math.hypot(dx,dy)||1;return {...limitAim(p,{x:p.x+dx/len*range,y:p.y+dy/len*range/(view.tilt||1)},range),manual:true};}
function overlayBattle(){
  const p=game.player;
  for(const e of game.entities){
    if(e.dead||!visibleToTeam(e,p.team))continue;
    const height=e.type==='hero'?e.def.id==='bulwark'?2.24:2.06:e.type==='tower'?2.5:e.type==='base'?1.95:e.type==='monster'?e.camp==='boss'?2.6:1.5:.84,lift=e.flight>0?1.1:game.time<e.jumpUntil?Math.sin((1-(e.jumpUntil-game.time)/e.jumpDuration)*Math.PI)*.8:0,at=rift3d.project(e.x,e.y,height+lift);
    if(at.x<-100||at.x>view.width+100||at.y<-60||at.y>view.height+60)continue;
    const allied=e.team===p.team,color=e.player?'#a8e65f':allied?'#63bedb':e.team===2?PURPLE:'#e77063',w=e.type==='hero'?72:e.type==='minion'?28:e.type==='base'?84:60,left=at.x-w/2;
    ctx.fillStyle='#08121fed';ctx.fillRect(left-1,at.y-1,w+2,9);ctx.fillStyle=color;ctx.fillRect(left,at.y,w*Math.max(0,e.hp/e.maxHp),5);
    if(e.type==='hero'){
      ctx.fillStyle='#1b344a';ctx.fillRect(left,at.y+6,w,2);ctx.fillStyle='#57a2ef';ctx.fillRect(left,at.y+6,w*Math.max(0,(e.mana??400)/(e.maxMana||400)),2);
      if(e.shield>0){ctx.fillStyle='#deeeff';ctx.fillRect(left,at.y+3,Math.min(w,w*e.shield/e.maxHp),2);}
      const ticks=Math.min(8,Math.floor(e.maxHp/500));ctx.fillStyle='#06101c9c';for(let i=1;i<=ticks;i++)ctx.fillRect(left+i*w/(ticks+1),at.y,1,5);
      const bx=left-10,by=at.y+3;ctx.beginPath();ctx.moveTo(bx,by-10);ctx.lineTo(bx+9,by);ctx.lineTo(bx,by+10);ctx.lineTo(bx-9,by);ctx.closePath();ctx.fillStyle='#101e28';ctx.fill();ctx.strokeStyle=e.player?'#e6d794':'#89a7ae';ctx.lineWidth=1.4;ctx.stroke();ctx.font='bold 10px "Chakra Petch"';ctx.textAlign='center';ctx.fillStyle='#eef3dc';ctx.fillText(e.level,bx,by+3);
      ctx.shadowColor='#000';ctx.shadowBlur=3;ctx.font='11px "Noto Sans Thai"';ctx.fillStyle=e.player?'#e4e7a2':allied?'#cae6ed':'#f2b6a7';ctx.fillText(e.clientName||e.def.name,at.x,at.y-5);if(e.stun>0){ctx.fillStyle='#ffe8a2';ctx.fillText('สตัน',at.x,at.y-20);}ctx.shadowBlur=0;
    }
    if(e.player&&e.recall>0){const feet=rift3d.project(e.x,e.y,.1);ctx.fillStyle=BLUE;ctx.textAlign='center';ctx.font='12px "Noto Sans Thai"';ctx.fillText('กลับฐาน '+e.recall.toFixed(1),feet.x,feet.y+22);}
  }
  for(const f of effects){if(f.type!=='text')continue;const at=rift3d.project(f.x,f.y,1.6);ctx.globalAlpha=Math.max(0,f.life/f.max);ctx.fillStyle=f.color;ctx.font='bold 17px "Chakra Petch"';ctx.textAlign='center';ctx.fillText(f.text,at.x,at.y-(1-f.life/f.max)*30);ctx.globalAlpha=1;}
  if(p.dead){ctx.fillStyle='#d8ffff';ctx.font='bold 16px "Noto Sans Thai"';ctx.textAlign='center';ctx.fillText('เกิดใหม่ใน '+Math.ceil(p.respawn)+' วินาที',view.width/2,view.height*.7);}renderMini();
}

draw=function(){if(!rift3d||rendererFailed)return fallbackDraw();if(!view.width||!view.height)return;try{rift3d.render(game?{...game,effects:effects.concat((game.wards||[]).filter(w=>w.team===game.player.team).map(w=>({type:'ring',fxId:'ward'+w.source+':'+w.until,x:w.x,y:w.y,radius:18,color:'#7dedee',life:1,max:1})),(game.projectiles||[]).map(p=>({type:'shot',fxId:'arrow'+p.id,x:p.x-p.dx*40,y:p.y-p.dy*40,tx:p.x,ty:p.y,color:p.color||(p.team===0?BLUE:RED),life:1,max:1})))}:null,{follow:camera.follow,aim:skillAim,aimInfo:game&&skillAim?skillInfo(game.player,skillAim.action):null,selected:selected.id,visible:e=>!game||visibleToTeam(e,game.player.team)});ctx.clearRect(0,0,view.width,view.height);if(game)overlayBattle();}catch(error){rendererFailed=true;canvas3d.hidden=true;showGraphicsStatus(-1,HEROES.length);console.error('3D frame failed',error.message);fallbackDraw();}};
$('qualityBtn').onclick=()=>{if(rift3d&&!rendererFailed)$('qualityBtn').textContent='ภาพ: '+rift3d.quality();};
let previewDrag=null;$('heroFigure').onpointerdown=e=>{previewDrag={id:e.pointerId,x:e.clientX};$('heroFigure').setPointerCapture(e.pointerId);};$('heroFigure').onpointermove=e=>{if(previewDrag?.id!==e.pointerId||!rift3d)return;rift3d.turnPreview((e.clientX-previewDrag.x)*.015);previewDrag.x=e.clientX;};$('heroFigure').onpointerup=$('heroFigure').onpointercancel=()=>{previewDrag=null;};
for(const [id,mode]of [['heroTargetBtn','hero'],['towerTargetBtn','tower']])$(id).onclick=()=>{$('targetMode').value=$('targetMode').value===mode?'nearest':mode;$(id).classList.toggle('active',$('targetMode').value===mode);$(id==='heroTargetBtn'?'towerTargetBtn':'heroTargetBtn').classList.remove('active');};
const updateSkillControls=()=>{for(const button of document.querySelectorAll('[data-action]')){const action=button.dataset.action;if(!['q','w','e'].includes(action))continue;button.onpointerdown=e=>{if(skillAim||controlsBlocked()||game.player.cd[action]>0)return;e.preventDefault();button.setPointerCapture(e.pointerId);const p=game.player,info=skillInfo(p,action);skillAim={id:e.pointerId,action,origin:{x:e.clientX,y:e.clientY},aim:info.mode==='self'?{x:p.x,y:p.y}:aimFor(p,info.range||450),dragged:false,cancelled:false};button.classList.add('aiming');};button.onpointermove=e=>{if(skillAim?.id!==e.pointerId)return;const dx=e.clientX-skillAim.origin.x,dy=e.clientY-skillAim.origin.y,len=Math.hypot(dx,dy);skillAim.cancelled=len>145;const info=skillInfo(game.player,action);if(len>9&&info.mode!=='self'){skillAim.dragged=true;skillAim.aim=manualSkillAim(dx*4,dy*4,game.player,action);pointer=skillAim.aim;}$('cancelSkill').hidden=!skillAim.cancelled;};button.onpointerup=e=>{if(skillAim?.id!==e.pointerId)return;const aim=skillAim;skillAim=null;button.classList.remove('aiming');$('cancelSkill').hidden=true;if(!aim.cancelled&&!controlsBlocked()){pointer=aim.aim;useSkill(action,null,aim.aim);}};button.onpointercancel=button.onlostpointercapture=e=>{if(skillAim?.id!==e.pointerId)return;skillAim=null;button.classList.remove('aiming');$('cancelSkill').hidden=true;};}};
updateSkillControls();
